INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q2', 'Which AI approach most directly supports understanding biological intelligence behavior as a scientific goal?', '["Weak AI", "Applied AI", "Cognitive AI", "Strong AI"]', 'Cognitive AI', 'There are three main AI goals: (1) Weak AI — build tools that do specific tasks (like chess engines). (2) Strong AI — build machines with general human-like intelligence. (3) Cognitive AI — study how humans and animals think, then use AI to model and understand that biological intelligence. Since the question asks about ''understanding biological intelligence as a scientific goal,'' Cognitive AI is the answer.', 'Artificial Intelligence', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q3', 'In client-server database architecture, what is the primary role of the server?', '["Provide the GUI for end users", "Initiate all network connections and poll clients for updates", "Store and manage shared data, enforce ACID properties, and process client requests", "Cache all user sessions locally for offline access"]', 'Store and manage shared data, enforce ACID properties, and process client requests.', 'In a client-server setup, the server is the central powerhouse. It stores all shared data in a database, handles queries sent by clients, enforces ACID properties (Atomicity, Consistency, Isolation, Durability) to keep data reliable, and sends results back to clients. The server does NOT show GUIs — that is the client''s job.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q4', 'Which automaton is powerful enough to recognize the language L = {aⁿbⁿcⁿ | n ≥ 1}?', '["DFA", "Linear Bounded Automaton (LBA)", "NFA", "Pushdown Automaton (PDA)"]', 'Linear Bounded Automaton (LBA)', 'Think of automata as a language-power hierarchy: DFA/NFA handle Regular languages → PDA handles Context-Free languages → LBA handles Context-Sensitive languages → Turing Machines handle all Recursively Enumerable languages. The language {aⁿbⁿcⁿ} requires counting three things simultaneously, which is beyond what a PDA (one stack) can do. An LBA is exactly powerful enough for such context-sensitive languages.', 'Automata Theory', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q5', 'In two-phase locking (2PL), during which phase may a transaction acquire locks but not release any?', '["Growing phase", "Commit phase", "Validation phase", "Shrinking phase"]', 'Growing phase', 'Two-Phase Locking has two phases: (1) Growing phase — the transaction can only ACQUIRE new locks; it cannot release any. (2) Shrinking phase — the transaction can only RELEASE locks; it cannot acquire new ones. This rule ensures serializability (conflict-free scheduling). Once you release even one lock, you''ve entered the shrinking phase.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q6', 'To extend the connectivity of processor bus we use:', '["SCSI", "PCI", "Controllers", "Multi bus"]', 'Multi bus', 'A single processor bus can become a bottleneck when many devices try to communicate simultaneously. The solution is a Multi-bus architecture: multiple buses (e.g., a fast local bus near the CPU, and slower expansion buses for peripherals) working in parallel. This extends connectivity and reduces congestion, allowing more devices to communicate efficiently.', 'Computer Architecture', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q7', 'Combinational circuit differ from sequential circuit primarily because', '["Combinational circuit cannot be built using logic circuit", "The output of combinational circuit depends only on the present input, not on past output.", "Sequential circuit have no feedback while combinational circuit do", "The combinational circuit requires clock signal, but sequential circuit do not"]', 'The output of combinational circuit depends only on the present input, not on past output.', 'Combinational circuits (e.g., AND gates, multiplexers) have NO memory — their output depends ONLY on the current inputs. Change the inputs, the output changes instantly. Sequential circuits (e.g., flip-flops, registers) DO have memory — their output depends on both current inputs AND past states (stored via feedback). This is the fundamental difference.', 'Digital Logic', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q8', 'Why is Greedy Best-First Search not guaranteed to be optimal or complete?', '["It ignores path cost g(n) and relies only on h(n)", "It always chooses the shallowest node", "It expands nodes in FIFO order", "It requires full knowledge of the goal state in advance"]', 'It ignores path cost g(n) and relies only on h(n).', 'Greedy Best-First Search only looks at h(n) — how close a node seems to the goal — and completely ignores g(n), the actual cost already paid to reach that node. This makes it fast but blind to wasted effort. It can get stuck in loops or go down expensive paths that look close to the goal. A* fixes this by using f(n) = g(n) + h(n), balancing both cost so far and estimated remaining cost.', 'Artificial Intelligence', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q9', 'From the following statement which is correct about this pointer in c++?', '["This pointer passed as hidden argument in all non-static variables of the class.", "This pointer passed as hidden argument in all static variables of the class.", "This pointer passed as hidden argument in all static function of the class.", "This pointer passed as hidden argument in all function of the class."]', 'This pointer passed as hidden argument in all non-static variables of the class.', 'In C++, every non-static member function secretly receives an extra hidden parameter called ''this'', which is a pointer to the object that called the function. This lets the function know which specific object it is working on. Static member functions belong to the class itself (not any object), so they have no ''this'' pointer. Static variables also belong to the class, not an instance.', 'Programming', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q10', 'In class diagram, if class Car has solid diamond points to class Engine, what does this indicates?', '["Car uses Engine temporarily", "Engine can exist independently of the Car", "Engine is the part of Car and cannot exist without it", "Car inherits from Engine"]', 'Engine is the part of Car and cannot exist without it.', 'In UML class diagrams, two types of ''whole-part'' relationships exist: Aggregation (hollow diamond) — the part can live independently (e.g., a Professor can exist without a University). Composition (solid/filled diamond) — the part CANNOT exist without the whole (e.g., an Engine is created and destroyed with the Car). The solid diamond from Car to Engine means Engine is completely owned by Car.', 'Software Engineering', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q11', 'The amount of time the algorithm takes on the smallest possible set of inputs is called_____', '["Average time", "Small time", "Worst time", "Best time"]', 'Best time', 'Algorithm analysis considers three cases: Best case — the algorithm runs on the most favorable input (e.g., the target is already in position 0 for linear search). Average case — typical/random input. Worst case — the most unfavorable input. Best time complexity describes how fast the algorithm runs on the smallest or most ideal input.', 'Algorithms', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q12', 'For a weak entity set to be meaningful, it must be associated with another entity set, called the', '["Identifying set", "Strong entity set", "Neighbor set", "Owner set"]', 'Strong entity set', 'A weak entity has no primary key of its own — it depends on another entity to be identified. For example, a ''Dependent'' (child/spouse) entity needs an ''Employee'' entity to exist and be identified. The entity it depends on is called the strong entity set (also called the identifying entity set). Without the strong entity, the weak entity cannot exist or be uniquely identified.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q13', 'Which one of the following is not the application level service?', '["Proxies and agents", "Installing a new service", "E-mail configuration", "Quality of service"]', 'Installing a new service', 'Application layer services (OSI Layer 7) are things users directly interact with: email (SMTP/POP3), web browsing (HTTP), proxies, agents, DNS, QoS policies, etc. ''Installing a new service'' is a system administration task — it happens at the OS/infrastructure level, not as an application-layer service. It''s an administrative activity, not a network protocol service.', 'Networking', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q14', 'A language that allows the DBA or user to describe and name the entities, attributes, and relationships required for the application is__________', '["Transaction control language (TCL)", "Data control language (DCL)", "Data Manipulation Language (DML)", "Data Definition Language (DDL)"]', 'Data Definition Language (DDL)', 'SQL has four sub-languages: DDL (Data Definition Language) — defines structure: CREATE, ALTER, DROP tables/schemas. DML (Data Manipulation Language) — manipulates data: SELECT, INSERT, UPDATE, DELETE. DCL (Data Control Language) — controls access: GRANT, REVOKE. TCL (Transaction Control Language) — manages transactions: COMMIT, ROLLBACK. DDL is for describing and naming entities, attributes, and relationships.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q15', 'Which one of the following is linear data structure?', '["Tree", "Array", "Queue", "Linked list"]', 'Array', 'Data structures are either linear (elements arranged in a sequence, one after another) or non-linear (elements in a hierarchy/network). Linear: Array, Linked List, Stack, Queue. Non-linear: Tree, Graph. All four options are listed — Array, Queue, and Linked List are all linear. The question asks which ONE is linear, implying the other options are not all linear; Array is the classic textbook example of a linear data structure.', 'Data Structures', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q16', 'What is the main purpose of syntax-directed translation in a compiler?', '["To interleave semantic analysis with syntax analysis using attributes attached to grammar symbols", "To generate optimized machine code directly", "To tokenize the source code", "To replace the parser with a finite automaton"]', 'To interleave semantic analysis with syntax analysis using attributes attached to grammar symbols.', 'Syntax-Directed Translation (SDT) attaches semantic rules (called actions) to grammar productions. As the parser builds the parse tree, it simultaneously evaluates these semantic rules (computing types, generating intermediate code, etc.). This elegantly merges syntax analysis and semantic analysis into one pass, rather than doing them in completely separate phases.', 'Compiler Design', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q17', 'What will be the output of the following program segment?
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q18', 'Which keyword is used in Java to create a subclass that inherits from a superclass?', '["Inherits", "Superclass", "Extends", "Implements"]', 'Extends', 'Java uses the ''extends'' keyword to create a subclass (child class) that inherits fields and methods from a superclass (parent class). Example: class Dog extends Animal { }. ''implements'' is used for interfaces, not class inheritance. ''inherits'' and ''superclass'' are not Java keywords.', 'Programming', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q19', 'What is the output of the following C++ code fragment?
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q20', '___________is a collection of related fields that can be treated as a unit by some application program.', '["Rows", "Field", "Record", "Database"]', 'Record', 'In database terminology: Field (attribute) — a single piece of data (e.g., ''Name''). Record (tuple/row) — a collection of related fields treated as one unit (e.g., one student''s full information: ID + Name + Age). Table (relation) — a collection of records. Database — a collection of tables. A record is the unit that a program typically reads or writes at once.', 'Database', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q21', 'Straight directed translation uses:', '["Purely lexical rules", "Backtracking algorithms", "Grammar without attributes", "Grammar with sematic rule"]', 'Grammar with semantic rule', 'Syntax-Directed Translation (SDT) directly embeds semantic rules (actions) into grammar productions. These rules are written alongside grammar rules and describe how to compute values or generate code as parsing proceeds. This ''straight directed translation'' approach relies on grammar augmented with semantic rules, not pure lexical rules or backtracking.', 'Compiler Design', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q22', 'Which one of the following is the first operation or step in CPU instruction cycle?', '["Executing the instruction", "Handling interrupt", "Decoding the instruction", "Fetching the instruction"]', 'Fetching the instruction', 'The CPU instruction cycle (fetch-decode-execute) always starts by FETCHING the next instruction from memory (using the Program Counter to find its address). Then it DECODES the instruction to understand what operation is needed. Then it EXECUTES the operation. Interrupt handling happens after execution, not before fetching.', 'Computer Architecture', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q23', 'Which search strategy tries to expand the node that is closest to the goal, on the grounds that this is likely to lead to a solution quickly; Thus, it evaluates nodes by using just the heuristic function: f ( n) = h ( n).', '["Uniform-cost search", "Greedy best-first search", "Depth-first search", "A* search"]', 'Greedy best-first search', 'Greedy Best-First Search is driven entirely by the heuristic h(n) — an estimate of how close a node is to the goal. It always expands the node that looks closest to the goal, ignoring how much it cost to get there. The evaluation function is simply f(n) = h(n). This makes it ''greedy'' — it takes the locally best-looking option without considering the full path cost.', 'Artificial Intelligence', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q24', 'Which one of the following is a top-down parser without backtracking?', '["LR parser", "Brute force parser", "Operator precedence parser", "Predictive parser"]', 'Predictive parser', 'Top-down parsers start from the root (start symbol) and try to derive the input. A Predictive Parser is a top-down parser that uses a lookahead token to decide which production to apply — NO backtracking needed. It uses a parsing table (LL(1) parsers are predictive). Brute-force parsers use backtracking. LR and Operator-precedence parsers are bottom-up.', 'Compiler Design', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q25', 'How many layers are there in OSI reference model?', '["7", "6", "5", "4"]', '7', 'The OSI (Open Systems Interconnection) model has exactly 7 layers, from bottom to top: (1) Physical, (2) Data Link, (3) Network, (4) Transport, (5) Session, (6) Presentation, (7) Application. A common mnemonic: ''Please Do Not Throw Sausage Pizza Away.''', 'Networking', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q26', 'Which one of the following is a computer structural component that provides for communication among CPU, main memory and I/O?', '["System unit", "Computer network", "CPU", "System interconnection"]', 'System interconnection', 'A computer has four main structural components: CPU, Main Memory (RAM), I/O Modules, and System Interconnection. The system interconnection (commonly the system bus) provides the communication paths between the CPU, memory, and I/O devices. Without it, these components cannot exchange data or control signals.', 'Computer Architecture', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q27', 'Assume that we are able to specify that Mr. Getahun can view the database record, but cannot change the value of the record. Which security management technique was used in this scenario?', '["Access Control", "Availability", "Non-repudiation", "Integrity"]', 'Access Control', 'Access Control is the security technique that defines WHO can do WHAT to WHAT resources. It grants or restricts permissions (read, write, execute, delete). In this scenario, Mr. Getahun has read-only access — he can VIEW but not MODIFY. This is a classic Access Control List (ACL) permission assignment.', 'Security', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q28', 'Suppose, a developer proposes using deferred update with no checkpoints in a hightransaction OLTP system. What is the most serious drawback?', '["Log scans become prohibitively expensive after long uptime", "Increased disk I/O due to frequent page copying", "Shared locks cannot be used", "View serializability cannot be ensured"]', 'Log scans become prohibitively expensive after long uptime.', 'Deferred update (no-undo/redo) writes changes to disk only after a transaction commits. During recovery, the system must scan the log from the very beginning to redo committed transactions. Without checkpoints, this log scan must go all the way back to the start of time, which becomes extremely slow after a system has been running for a long time with many transactions.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q29', 'Which one of the following function of operating system is categorized under process management?', '["Allocates the device in the efficient way", "De-allocates the resources.", "Allocates the memory when the process requests it to do so.", "Allocates the processor (CPU) to a process"]', 'Allocates the processor (CPU) to a process.', 'OS functions are organized by resource type: Process Management — creating, scheduling, and terminating processes, allocating CPU time. Memory Management — allocating and deallocating RAM. I/O Management — handling device drivers and I/O operations. Allocating the CPU to a process is the core job of the CPU scheduler, which falls under Process Management.', 'Operating Systems', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q30', 'Which of the following statements is TRUE?', '["Every regular language is context-free.", "Every context-free language is regular.", "Every context-sensitive language is regular.", "Every recursively enumerable language is recursive"]', 'Every regular language is context-free.', 'The Chomsky hierarchy is a strict containment: Regular ⊂ Context-Free ⊂ Context-Sensitive ⊂ Recursively Enumerable. Since Regular languages are a subset of Context-Free languages, every regular language IS also context-free. The reverse is not true — not every CFL is regular (e.g., {aⁿbⁿ} is CFL but not regular).', 'Automata Theory', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q31', '____________ is a data transfer method in computer organization and architecture that allows an I/O device to transfer data directly to or from memory without the involvement of the CPU.', '["Asynchronous data transfer", "Direct Memory Access (DMA)", "Interrupt-driven transfer", "Programmed I/O transfer"]', 'Direct Memory Access (DMA)', 'Normally the CPU controls every data transfer (programmed I/O), which wastes CPU cycles waiting. DMA (Direct Memory Access) is a hardware controller that lets I/O devices transfer data directly to/from RAM without CPU involvement. The CPU only initiates the transfer and gets an interrupt when it''s done, freeing it for other work. This greatly improves system performance.', 'Computer Architecture', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q32', 'Which one of the following php method is used to retrieve the information from the form control through the parameters sent in the URL?', '["$_REQUEST[]", "$_POST[]", "$_GET[]", "isset()"]', '$_GET[]', 'Insertion sort builds a sorted portion one element at a time. It takes the next unsorted element and ''inserts'' it into its correct position among the already-sorted elements by shifting larger elements right. Simple, stable, and efficient for small or nearly-sorted arrays (O(n) best case), but O(n²) in the worst case.', 'Web Development', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q33', 'Which statement is NOT true about digital signature?', '["Digital signature is not encryption algorithm", "In digital signature Sender encrypts message with its private key", "In digital signature Sender encrypts message with its public key", "Digital signature provides authentication services"]', 'In digital signature, Sender encrypts message with its public key.', 'In process synchronization, a semaphore is a shared counter used to control access to resources. wait() (also called P() or down()) decrements the semaphore — if it goes negative, the process blocks. signal() (also called V() or up()) increments the semaphore — if there are blocked processes, one is woken up. wait() is the operation a process calls BEFORE entering a critical section.', 'Security', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q34', 'Which one of the following ip address class uses first two octets for network addresses and last two for host addressing?', '["Class C", "Class D", "Class A", "Class B"]', 'Class B', 'IPv4 addresses are divided into classes by their first octet range: Class A: 1–126 (e.g., 10.x.x.x) — very large networks. Class B: 128–191 (e.g., 172.16.x.x) — medium networks. Class C: 192–223 (e.g., 192.168.x.x) — small networks. Class D: 224–239 — multicast. Class E: 240–255 — reserved. Any address starting with 128–191 is Class B.', 'Networking', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q35', 'Which of the following best defines a heuristic in the context of AI search?', '["A function that estimates how close a state is to the goal", "A guaranteed optimal path to the goal", "A method that always avoids revisiting states", "A brute-force enumeration of all possible states"]', 'A function that estimates how close a state is to the goal.', 'A heuristic function h(n) is an estimate (a ''smart guess'') of how far the current state n is from the goal. It does NOT guarantee the optimal path — it just guides the search toward promising directions. Good heuristics reduce the search space dramatically. Example: In a map navigation problem, straight-line distance to the destination is a heuristic.', 'Artificial Intelligence', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q36', 'Which one of the following party performs the technical evaluation work, using the evidence supplied by the developers, and additional testing of the product, to confirm that it satisfies the functional and assurance requirements specified in the security target?', '["Evaluator", "Certifier", "Sponsor", "Developer"]', 'Evaluator', 'In the Common Criteria (CC) security evaluation framework, three parties exist: Developer — builds the product. Evaluator — independently tests and verifies that the product meets the security requirements specified in the Security Target. Certifier — officially certifies the evaluation results. Sponsor — funds the evaluation. The Evaluator does the hands-on technical assessment.', 'Software Engineering', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q37', 'Assume that you have a huge company like university; bank industry, etc. have their own data center to store and control the different type of the data. Which type of RAID technology is the most preferable to use?', '["RAID level 3", "RAID level1", "RAID level 2", "RAID level 0"]', 'RAID level 1', 'RAID levels offer different tradeoffs: RAID 0 — striping only, no fault tolerance. RAID 1 — mirroring, exact copy on two disks, excellent fault tolerance. RAID 2/3 — bit/byte-level striping with dedicated parity. RAID 5 — block-level striping with distributed parity. For critical institutions (banks, universities) that cannot afford data loss, RAID 1 (full mirroring) is preferred for maximum data protection, even though it uses 50% of disk space for redundancy.', 'Computer Architecture', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q38', 'Which analysis technique is INAPPROPRIATE for determining the lower bound of comparison-based sorting, and why?', '["Decision tree model \u2014 because it assumes only array indexing is allowed", "Recurrence relations \u2014 because sorting isn\u2019t naturally recursive", "Asymptotic analysis \u2014 because it ignores constants", "Decision tree model \u2014 because it gives an information-theoretic lower bound of \u03a9(nlogn)"]', 'Recurrence relations — because sorting isn’t naturally recursive.', 'The Decision Tree Model is the standard formal tool for proving that comparison-based sorting requires at least Ω(n log n) comparisons. It gives an information-theoretic lower bound by analyzing the minimum tree height needed to distinguish n! possible orderings. Recurrence relations are useful for analyzing recursive algorithms, but sorting''s lower bound proof is not naturally derived from recurrences — it comes from the decision tree argument.', 'Algorithms', 'hard', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q39', 'In CSS, which property is used to change the text color of an element?', '["text-color", "font-color", "color", "Foreground"]', 'color', 'In CSS, the ''color'' property sets the foreground (text) color of an element. Example: p { color: red; }. Common mistakes: ''text-color'' and ''font-color'' do not exist in CSS. ''Foreground'' is not a valid CSS property. Always use ''color'' for text color.', 'Web Development', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q40', 'From the flowing function which one is used to create the table', '["CREATE table_name (column_name, column type);", "CREATE table_name (column_type, column name);", "CREATE TABLE table_name (column_name, column type);", "CREATE TABLE table_name (column_type, column name);"]', 'CREATE TABLE table_name (column_name, column type);', 'The correct SQL syntax to create a table is: CREATE TABLE table_name (column_name data_type, ...); Key rules: Both ''CREATE'' and ''TABLE'' must be written. Column definitions go inside parentheses with the column name FIRST, then the data type. Options missing ''TABLE'' or reversing name/type are wrong.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q41', 'What is the primary function of an operating system?', '["To connect to the internet", "To create documents and spreadsheets", "To design computer hardware", "To act as an intermediary between users and computer hardware"]', 'To act as an intermediary between users and computer hardware.', 'An operating system (OS) is the software layer that sits between the user/applications and the hardware. It manages CPU, memory, storage, and I/O devices, and provides a safe, convenient interface for programs to use these resources. Without an OS, every application would need to directly control hardware — which is impractical and unsafe.', 'Operating Systems', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q42', 'How much time units or T( n) taken to compute the following piece of code?
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q43', 'An object oriented principle that contains information in an object, exposing only selected information is____________.', '["Abstraction", "Inheritance", "Polymorphism", "Encapsulation"]', 'Encapsulation', 'Encapsulation bundles data (attributes) and the methods that operate on that data together into a class, hiding internal implementation details. It uses access modifiers (private, protected, public) to expose only what''s necessary. Think of it like a capsule pill — the medicine (data) is enclosed inside the shell (class), and you only interact with the outer interface.', 'Programming', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q44', 'Stack is follows ____policy:', '["LIFO", "FIFO", "FILO", "FCFS"]', 'LIFO', 'A Stack is a linear data structure that follows LIFO — Last In, First Out. The last element pushed onto the stack is the first one popped off. Think of a stack of plates: you add to the top and remove from the top. FIFO (First In, First Out) is the policy of Queues, not stacks.', 'Data Structures', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q45', 'From the following alternatives which one is FALSE about database system?', '["It is very difficult to protect a file under the system", "In database system the user is not required to write the procedures", "In database system, DBMS provides a good protection mechanism.", "It contains a wide variety of sophisticated techniques to store and retrieve the data."]', 'It is very difficult to protect a file under the system.', 'This question asks for the FALSE statement about database systems. Modern DBMS (Database Management Systems) like MySQL, Oracle, and PostgreSQL provide robust protection mechanisms including access control, encryption, and audit trails. So saying ''it is very difficult to protect a file under the system'' is FALSE — DBMSs actually make protection much EASIER compared to file systems.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q46', 'Which one of the following is categorized under Log based Recovery Techniques in database?', '["Recovery in Multi-database Systems", "ARIES Recovery Algorithm", "Shadow Paging Technique", "Deferred Database Modification"]', 'ARIES Recovery Algorithm', 'Database recovery techniques fall into two categories: Log-Based Recovery — uses a transaction log to undo/redo operations. Examples: Deferred Modification, Immediate Modification, ARIES Algorithm. Shadow Paging — maintains a shadow (backup) copy of pages, not log-based. ARIES (Algorithm for Recovery and Isolation Exploiting Semantics) is the most advanced log-based recovery algorithm, used in modern databases.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q47', 'What is the first step to convert context free grammar (CFG) into Greibach Normal Form (GNF)?', '["Convert the grammar into CNF", "If any production rule in the grammar is not in GNF form, convert it.", "Convert the grammar into GNF", "If the grammar exists left recursion, eliminate it."]', 'If the grammar exists left recursion, eliminate it.', 'Converting a CFG to Greibach Normal Form (GNF) requires all productions to start with a terminal. The steps are: (1) First, eliminate left recursion (A → Aα causes infinite loops). (2) Then order non-terminals and eliminate indirect left recursion. (3) Finally, convert each production to GNF form. Eliminating left recursion is always the very first step.', 'Automata Theory', 'hard', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q48', 'A user installs a new printer. The OS automatically detects and configures it. This is an example of:', '["Plug-and-play functionality", "Manual driver installation", "Manual hardware management", "Resource allocation"]', 'Plug-and-play functionality', 'Plug-and-Play (PnP) is an OS feature that automatically detects, configures, and installs drivers for newly connected hardware (like USB devices, printers, monitors). The OS communicates with the device to learn its requirements and assigns it the necessary system resources (IRQ, I/O ports, memory) without manual user configuration.', 'Operating Systems', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q49', 'Which of the following is NOT property of an algorithm?', '["Finiteness", "Definiteness", "Correctness", "Platform dependence"]', 'Platform dependence', 'A proper algorithm must have these properties: Finiteness — must terminate after a finite number of steps. Definiteness — each step must be precisely defined. Input — zero or more inputs. Output — one or more outputs. Effectiveness — each step must be doable. Correctness — produces correct output. Platform dependence is NOT a property — a good algorithm should be platform-INDEPENDENT (the same logic works regardless of hardware/OS).', 'Algorithms', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q50', 'Which Redundant Array of Independent Disks (RAID) is known by striping with parity and fault tolerance?', '["RAID 2", "RAID 1", "RAID 5", "RAID 0"]', 'RAID 5', 'RAID 5 uses block-level striping with distributed parity across all disks. Data AND parity are spread across all drives — unlike RAID 3/4 where parity is on a dedicated disk. RAID 5 can tolerate one disk failure (using parity to reconstruct lost data) while still providing improved read performance. It''s the most popular RAID level for servers needing both performance and fault tolerance.', 'Computer Architecture', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q51', 'Assume that you are computer science expert and you need to develop large programs within short period of time. Finally, you have planned to provide portable program to the concerned body. Which type of programming language is preferable for the above scenario?', '["Low level", "Machine level", "High level", "Assembly"]', 'High level', 'High-level languages (Python, Java, C++) are: Portable — same code runs on different platforms. Readable — close to human language, easy to write and maintain. Fast to develop — write complex programs quickly. Low-level and assembly languages are fast but hardware-specific and not portable. For large projects with tight deadlines requiring portability, high-level is always the right choice.', 'Programming', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q52', 'Which type of heuristic search strategy that evaluates nodes by combining g ( n), the cost to reach the node, and h ( n.), the cost to get from the node to the goal: f ( n) = g ( n) + h ( n) Since g( n) gives the path cost from the start node to node n, and h( n) is the estimated cost of the cheapest path from n to the goal, we have f ( n) = estimated cost of the cheapest solution through n ?', '["A* search", "Greedy Best-First Search", "Uniform-cost search", "Depth-first search"]', 'A* search', 'A* (A-star) search uses f(n) = g(n) + h(n), where g(n) is the actual cost from the start to node n, and h(n) is the estimated cost from n to the goal. By combining both, A* is both complete (finds a solution if one exists) and optimal (finds the shortest path) — provided h(n) is admissible (never overestimates). It''s the gold standard of informed search algorithms.', 'Artificial Intelligence', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q53', 'If input is “a” is for syntax tree, which function is used to create tree?', '["mknode(num, value)", "mkleaf(num, value)", "mkleaf(id, entry)", "mknode(op, left, right)"]', 'mknode(op, left, right)', 'In syntax tree construction: mkleaf(id, entry) — creates a leaf node for an identifier. mkleaf(num, value) — creates a leaf node for a number. mknode(op, left, right) — creates an internal node for an operator with left and right children. For a syntax tree of an expression like ''a op b'', mknode creates the root operator node connecting the two operand leaves.', 'Compiler Design', 'hard', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q54', 'Suppose Mr. Negesa might act as Mr. Dereje and send message to Registrar X, the registrar might be lead to believe that message indeed come from Mr. Dereje. What types of attack Mr. Negesa has committed?', '["Denial of service", "Modification of message", "Masquerade", "Replay"]', 'Masquerade', 'A Masquerade attack (also called impersonation or spoofing) is when an attacker pretends to be a legitimate user to gain unauthorized access or deceive others. Mr. Negesa is pretending to be Mr. Dereje to trick the Registrar. Other attacks: Replay — reuses captured data. Modification — alters data in transit. Denial of Service — overwhelms a system to make it unavailable.', 'Security', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q55', 'From the following statement which one is disadvantage of waterfall model?', '["model is simple and easy to understand and use", "It is easy manage due to the rigidity of the model", "Not suitable for projects where requirements are at a moderate to high risk of changing", "In this model phases are processed and completed one at a time"]', 'Not suitable for projects where requirements are at a moderate to high risk of changing.', 'The Waterfall Model is sequential: Requirements → Design → Implementation → Testing → Maintenance. Its biggest disadvantage is inflexibility — once you move to the next phase, going back is costly. If requirements change midway (which is common in real projects), the entire process may need to restart. It works well only when requirements are very clear and stable from the beginning.', 'Software Engineering', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q56', 'Consider a directed line(->) from the relationship set advisor to both entity sets instructor and student. This indicates _________ cardinality', '["Many to one", "Many to many", "One to one", "One to many"]', 'Many to one', 'In ER diagrams, cardinality is shown with arrows: An arrow (→) pointing FROM relationship TO entity means ''at most one'' (one side). No arrow means ''many''. Here, the advisor relationship has arrows pointing TO both instructor AND student, meaning each advising relationship maps to exactly one instructor AND one student — but many advisor relationships can point to the same instructor. This is Many-to-One (many students advised by one instructor).', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q57', 'In a system, resources cannot be forcibly taken from processes; they must be released voluntarily. Which deadlock condition does this represent?', '["No Preemption", "Hold and Wait", "Mutual Exclusion", "Circular Wait"]', 'No Preemption', 'The four conditions for deadlock are: (1) Mutual Exclusion — resource held exclusively. (2) Hold and Wait — process holds resources while waiting for more. (3) No Preemption — resources cannot be forcibly taken away; a process must voluntarily release them. (4) Circular Wait — a cycle of processes each waiting for the next. ''Cannot be forcibly taken'' = No Preemption.', 'Operating Systems', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q58', 'Which statement is WRONGLY described about code generation?', '["Code generation can be considered as the start phase of compilation", "The target program is the output of the code generator", "The code generation phase needs complete error-free intermediate code as an input requires", "It used to produce the target code for three-address statements."]', 'Code generation can be considered as the start phase of compilation.', 'Code generation is the FINAL phase of a compiler (after lexical analysis, parsing, semantic analysis, and optimization). It takes the intermediate code as input and produces the target machine code. Saying it is the ''start phase'' is completely wrong — it''s actually the last phase. All earlier phases must successfully complete before code generation begins.', 'Compiler Design', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q59', '____________is a service that allows organizations and individuals to post a website or a web page onto the Internet.', '["Web hosting", "Internet service provider", "Web client", "Domain name registration"]', 'Web hosting', 'Web Hosting is a service (provided by companies like AWS, GoDaddy, Bluehost) that provides the servers, storage, and infrastructure needed to make a website accessible on the internet. An ISP provides internet access. Domain name registration gives a website its URL address. Web hosting is specifically about storing and serving website files.', 'Web Development', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q60', 'In singly linked list, the node contains', '["Data and index", "Data and one pointer ( the next node)", "Only data", "Data and two pointers"]', 'Data and one pointer (the next node)', 'A Singly Linked List node contains exactly two parts: (1) Data — the actual value stored. (2) Next pointer — the memory address (pointer) of the next node in the list. The last node''s next pointer is NULL. Unlike doubly linked lists (two pointers: next and previous) or arrays (index-based), singly linked lists only point forward.', 'Data Structures', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q61', 'Which of the following statement is non-functional requirement?', '["The system allow user to generate PDF report.", "The system respond to user\u2019s request within 2 second under normal load", "The system allow user to store data on relational database", "The system allow user to submit emergency report"]', 'The system respond to user’s request within 2 seconds under normal load.', 'Requirements are classified as: Functional — what the system should DO (features, behaviors, functions). Non-functional — HOW the system should perform (quality attributes). ''Respond within 2 seconds'' is a Performance requirement, which is a non-functional requirement. Generating PDFs, storing data, submitting reports — those are functional (they describe actions the system performs).', 'Software Engineering', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q62', 'In object design, what does the contract typically includes?', '["The class diagram and sequence diagram", "Project budget and timeline", "Invariants, preconditions, post conditions", "The use case names and actors role"]', 'Invariants, preconditions, post conditions.', 'In object design, a contract formally specifies: Preconditions — conditions that must be TRUE before calling a method (caller''s responsibility). Postconditions — conditions guaranteed to be TRUE after the method executes (method''s promise). Invariants — conditions that must always be TRUE for an object (class-level constraints). Contracts enable Design by Contract (DbC) programming.', 'Software Engineering', 'hard', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q63', 'Which of the following OSI layers is NOT correctly matched to its corresponding data Units (PDU)?', '["Application layer ---> Data", "Transport layer ---> Segment", "Physical layer ---> Bit", "Network layer ---> Frame"]', 'Network layer ---> Frame.', 'OSI layer PDUs (Protocol Data Units): Application/Presentation/Session → Data. Transport → Segment. Network → Packet. Data Link → Frame. Physical → Bit. The Network layer uses PACKETS, not Frames. Frames are the PDU of the Data Link layer (Layer 2). This is a common exam trick — Network layer = Packet, Data Link layer = Frame.', 'Networking', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q64', 'Which data structure follows LIFO principle?', '["Graphs", "Queues", "Stacks", "Trees"]', 'Stacks', 'LIFO = Last In, First Out. The data structure that uses LIFO is a Stack. Imagine a stack of books — you can only add or remove from the top. The last book placed is the first one picked up. Queues use FIFO (First In, First Out). Trees and Graphs are non-linear structures with their own traversal methods.', 'Data Structures', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q65', 'Consider the following code snippet
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q66', 'Which type of grammar is used to generate all possible patterns of strings in a given formal language?', '["Context-free", "Context-sensitive", "Recursively enumerable", "Regular"]', 'Recursively enumerable', 'In the Chomsky hierarchy: Type 3 — Regular grammars. Type 2 — Context-Free grammars. Type 1 — Context-Sensitive grammars. Type 0 — Recursively Enumerable (Unrestricted) grammars. Type 0 has no restrictions on productions and can generate ALL possible formal languages. It''s recognized by a Turing Machine, the most powerful computational model.', 'Automata Theory', 'hard', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q67', 'Which tool is used to troubleshoot the network connectivity?', '["Ipconfig", "Ping", "Encryption", "Firewall"]', 'Ping', 'Ping is the fundamental network diagnostic tool. It sends ICMP (Internet Control Message Protocol) Echo Request packets to a target IP address and waits for Echo Reply packets. It tells you: Is the host reachable? How long does the round-trip take (latency)? How many packets were lost? ipconfig shows your own network configuration, not connectivity to other hosts.', 'Networking', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q68', 'The time complexity for binary search is__________', '["O(n*log(n )2)", "O(n2)", "O( n)", "O(logn)"]', 'O(log n)', 'In the HTML table model: <table> — the whole table. <tr> — table row. <th> — table header cell (bold and centered by default). <td> — table data cell (regular cell). To add a new row, you use <tr> and put <td> or <th> cells inside it. <thead>, <tbody>, <tfoot> are optional structural groupings.', 'Algorithms', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q69', 'Which type of access specifier is accessible within the same package or subclasses in a different package?', '["Public", "Default", "Private", "Protected"]', 'Protected', 'C++ access specifiers: private — accessible only within the same class. public — accessible from anywhere. protected — accessible within the same class AND by subclasses (derived classes). When you want subclasses to inherit and access members, but prevent outside code from accessing them directly, use protected.', 'Programming', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q70', 'What is the basic goal of Normalization?', '["To decrease data integrity", "To reduce redundancy", "To maximize transitive dependency", "To increase dependency"]', 'To reduce redundancy', 'Normalization is the process of organizing a relational database to minimize data redundancy (duplicate data) and eliminate update/insert/delete anomalies. It proceeds through Normal Forms: 1NF, 2NF, 3NF, BCNF, etc. Each step removes certain types of dependencies. The primary goal is always to reduce redundancy while maintaining data integrity.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q71', 'Which protocol is mostly used for communication between client and server in a web application?', '["FTP", "SMTP", "HTTP", "SSH"]', 'HTTP', 'HTTP (HyperText Transfer Protocol) is the foundation of data communication on the web. Browsers (clients) send HTTP requests to web servers, which respond with HTTP responses containing HTML, CSS, JavaScript, images, etc. HTTPS is the secure version. FTP is for file transfer. SMTP is for email. SSH is for secure remote login.', 'Web Development', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q72', 'Which of the following layers is responsible for encryption, translation and compression?', '["Presentation layer", "Data link layer", "Transport layer", "Network layer"]', 'Presentation layer', 'OSI Layer 6 — the Presentation Layer — acts as a translator between the application and the network. Its three main jobs are: Translation — converting data formats (e.g., ASCII to EBCDIC). Encryption/Decryption — securing data. Compression/Decompression — reducing data size for faster transmission. It ensures data sent by one system can be understood by another.', 'Networking', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q73', 'What is the extension of JavaScript file?', '[".javaS", ".JS", ".java", "CSS"]', '.JS', 'JavaScript files use the .js extension (case-insensitive, so .JS is also correct). JavaScript is a scripting language used to make web pages interactive. .java is for Java programs, .css is for stylesheets. When linking a JS file in HTML: <script src=''script.js''></script>.', 'Web Development', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q74', 'Why is perception still a challenge for AI—even though systems can recognize faces?', '["Because perception is unrelated to reasoning", "Because AI lacks actuators", "Because perception requires common-sense knowledge and robust natural language understanding in open ended worlds", "Because sensors are too expensive"]', 'Because perception requires common-sense knowledge and robust natural language understanding in open ended worlds.', 'Even though AI can recognize faces (narrow task), true perception involves understanding context, meaning, and nuance in open-ended, unpredictable real-world environments. This requires common-sense knowledge (knowing that a wet road means it rained) and natural language understanding in all its ambiguity. These remain unsolved challenges — perception in controlled domains ≠ perception in the open world.', 'Artificial Intelligence', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q75', 'Which service used to translate domain names to ip address?', '["HTTPS", "DHCP", "HTTP", "DNS"]', 'DNS', 'DNS (Domain Name System) is the internet''s phone book. When you type www.google.com, your computer doesn''t know where that is — DNS translates the human-readable domain name into an IP address (like 142.250.80.46) that routers can use to direct your request. DHCP assigns IP addresses to devices. HTTPS is for secure web browsing.', 'Networking', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q76', 'Which one of following monitors incoming and outgoing network traffic and decides whether to allow or block specific traffic based on a defined set of security rules?', '["Intrusion detection system (IDS)", "Proxy server", "Virtual Private network", "Firewall"]', 'Firewall', 'A Firewall is a network security device (hardware or software) that monitors incoming and outgoing traffic and enforces security rules to allow or block specific traffic. It acts as a barrier between trusted internal networks and untrusted external networks. IDS detects intrusions but doesn''t block them. A proxy server forwards requests. VPN creates encrypted tunnels.', 'Security', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q77', 'Consider attributes ID, CITY and NAME. Which one of this can be considered as a super key?', '["NAME", "ID", "CITY", "CITY, ID"]', 'CITY, ID', 'A Super Key is any set of attributes that can uniquely identify a tuple (row) in a table. A single attribute like NAME or CITY might not be unique (multiple people can share a name or city). ID might be unique by itself. But {CITY, ID} is definitely a super key because adding more attributes to a unique key always gives another super key. The combination of two attributes always qualifies.', 'Database', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q78', 'You want to ensure that a method calculateTax() in class Employee cannot be overridden by any subclass. What declaration achieves this?', '["Abstract double calculateTax();", "Final double calculateTax(){\u2026}", "Private double calculateTax(){\u2026}", "Static double calculateTax(){\u2026}"]', 'Final double calculateTax(){…}', 'In Java, the ''final'' keyword prevents a method from being overridden in any subclass. Declaring calculateTax() as final double calculateTax(){...} means no subclass can provide a different implementation. ''abstract'' is the opposite (must be overridden). ''private'' hides the method but doesn''t explicitly prevent overriding across all subclasses. ''static'' belongs to the class, not instances.', 'Programming', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q79', 'Which one of the following identifier name is INVALID in C++ programming language?', '["delete", "for_cpp", "jan2025", "Hello"]', 'delete', 'In C++, identifiers (variable/function names) cannot be reserved keywords. ''delete'' is a C++ keyword used to free dynamically allocated memory (delete ptr;). Therefore it cannot be used as an identifier name. ''for_cpp'', ''jan2025'', and ''Hello'' are all valid identifiers — they follow the rules (start with letter or underscore, contain letters/digits/underscores, not a keyword).', 'Programming', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q80', 'Which one of the following UML building block that defines the static part of the model and represents physical and conceptual elements?', '["Structural things", "Behavioral things", "An notational things", "Grouping things"]', 'Structural things', 'UML has three types of building blocks: Structural Things — static, physical/conceptual elements: classes, interfaces, components, nodes, use cases. Behavioral Things — dynamic, representing behavior over time: interactions, state machines. Grouping Things — organizational: packages, subsystems. Annotational Things — notes/comments. Structural things define WHAT the system IS.', 'Software Engineering', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q81', 'Which scenario is best suited for UDP rather than TCP protocol?', '["Live video streaming", "Email transmission", "Downloading the files", "Database update"]', 'Live video streaming', 'UDP (User Datagram Protocol) is connectionless and fast — it sends packets without guaranteeing delivery or order. TCP is connection-oriented and reliable but slower due to handshaking and retransmission. For live video/audio streaming, a tiny delay from TCP retransmission is worse than a dropped frame. Speed and low latency matter more than perfect delivery — that''s why UDP is preferred for real-time media.', 'Networking', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q82', 'Which type of transparency in distributed database system distributes a relation into sub relations where each sub relation is defined by a subset of the columns of the original relation?', '["Replication", "Location", "Horizontal", "Vertical"]', 'Vertical', 'In distributed databases, fragmentation divides a table: Horizontal fragmentation — splits by rows (each fragment has a subset of rows, same columns). Vertical fragmentation — splits by columns (each fragment has a subset of columns, same rows/key). Vertical fragmentation distributes a relation into sub-relations defined by a subset of COLUMNS. This allows different sites to store only the columns they need.', 'Database', 'hard', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q83', 'In which of the following Learning methods an agent receives feedback in the form of rewards or penalties to maximize cumulative reward?', '["Supervised learning", "Reinforcement learning", "Semi-supervised learning", "Unsupervised learning"]', 'Reinforcement learning', 'Machine learning types: Supervised — learns from labeled examples (input → correct output). Unsupervised — finds patterns in unlabeled data. Semi-supervised — mix of labeled and unlabeled. Reinforcement Learning — an agent takes actions in an environment and receives rewards (positive feedback) or penalties (negative feedback), learning to maximize cumulative reward over time. Used in game AI (AlphaGo), robotics, etc.', 'Artificial Intelligence', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q84', 'After deploying a new software system, users reports that the system slows during peak hour. Which software quality attribute primarily affected?', '["Maintainability", "Performance", "Reliability", "Usability"]', 'Performance', 'Software quality attributes include: Performance — how fast/responsive the system is under load. Reliability — does it work correctly and consistently. Usability — ease of use. Maintainability — ease of changing/updating. When users report slowness during peak hours (high load), the system is failing to perform fast enough under stress. This is a Performance issue.', 'Software Engineering', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q85', 'Which one of the following is WRONGLY stated about an importance of security policy?', '["To help minimize risk.", "To ensure the confidentiality, integrity and availability of data.", "To coordinate and enforce a security program across an organization.", "To use the system in a passive way"]', 'To use the system in a passive way.', 'A security policy serves to: minimize risk, ensure CIA (Confidentiality, Integrity, Availability), coordinate security practices organization-wide, provide guidelines for acceptable use, and actively protect systems. ''To use the system in a passive way'' is the WRONG answer — security policies are proactive and active, not passive. A passive security approach would actually be a vulnerability.', 'Security', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q86', 'Which of the following is NOT a task of the lexical analyzer?', '["Generating parse trees", "Correlating errors with line numbers", "Entering identifiers into the symbol table", "Stripping whitespace and comments"]', 'Generating parse trees', 'The Lexical Analyzer (scanner) is the first compiler phase. Its jobs include: tokenizing source code (identifying keywords, identifiers, numbers, operators), stripping whitespace and comments, entering identifiers into the symbol table, and correlating errors with source line numbers. It does NOT generate parse trees — that is the job of the Parser (syntax analysis), which comes AFTER lexical analysis.', 'Compiler Design', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q87', 'Which sorting algorithm compares each pair of adjacent elements from the beginning of an array and, if they are in reversed order, swaps them; if at least one swaps has been done, repeat step 1.', '["Insertion sort", "Bubble sort", "Selection sort", "Shell sort"]', 'Bubble sort', 'Bubble Sort repeatedly compares adjacent pairs and swaps them if they''re in the wrong order. After each full pass, the largest unsorted element ''bubbles up'' to its correct position at the end. The process repeats until no more swaps are needed (the array is sorted). It''s named ''bubble'' because values gradually bubble to their correct positions. Time complexity: O(n²) average and worst case.', 'Algorithms', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q88', 'Which one of the following computer security goal prevents the disclosure of sensitive information to unauthorized users or systems on computer networks?', '["Confidentiality", "Integrity", "Cyberspace", "Availability"]', 'Confidentiality', 'The three pillars of the CIA security triad: Confidentiality — ensures that data is accessible ONLY to authorized users. Integrity — ensures data has not been tampered with. Availability — ensures the system is accessible when needed. Preventing disclosure of sensitive information to unauthorized parties is precisely what Confidentiality means.', 'Security', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q89', 'Assume that you have IPv4 addresses in binary notation 11000001 10000011 00011011 11111111 and you are requested to change into dotted decimal notation. What is the equivalent IP address in decimal dotted notation?', '["192.174.27.255", "192.134.67.254", "193.130.28.254", "193.131.27.255"]', '193.131.27.255', 'Convert each 8-bit group: 11000001 = 128+64+1 = 193. 10000011 = 128+2+1 = 131. 00011011 = 16+8+2+1 = 27. 11111111 = 255. Result: 193.131.27.255. Quick tip: memorize powers of 2 (128,64,32,16,8,4,2,1) and add up the positions where there is a ''1'' bit.', 'Networking', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q90', 'ou have given that Grammar G1 −({S, A, B}, {a, b}, S, {S → AB, A → a, B → b}). Which one is terminal symbol in the give?', '["a,b", "S", "S \u2192 AB, A \u2192 a, B \u2192 b", "S,A,B"]', 'a, b', 'In formal grammar G = (V, Σ, S, P): V = {S, A, B} are non-terminal symbols (variables). Σ = {a, b} are terminal symbols (actual characters of the language). S is the start symbol. P = {S→AB, A→a, B→b} are productions. Terminal symbols are the actual alphabet symbols that appear in the final generated strings — they cannot be replaced further. Here, ''a'' and ''b'' are terminals.', 'Automata Theory', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q91', 'Among the following one is NOT the application of queue in the real world.', '["It is used in operating systems for handling interrupts.", "It is used to maintain the play list in media players in order", "It is used in Depth First search", "It is widely used as waiting lists for a single shared resource"]', 'It is used in Depth First search.', 'Queue (FIFO) is used for: OS interrupt handling, media player playlists, CPU scheduling, keyboard buffers, printer queues, BFS (Breadth-First Search). DFS (Depth-First Search) uses a STACK (LIFO), not a queue. Each node''s unvisited neighbors are pushed onto a stack and processed in LIFO order, giving DFS its depth-exploring behavior.', 'Data Structures', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q92', 'Which one of the following is disadvantage of circuit switching?', '["Predictable performance", "Low latency", "Guaranteed bandwidth", "Limited scalability"]', 'Limited scalability', 'Circuit switching (used in traditional telephone networks) establishes a dedicated communication path for the entire duration of a call. Advantages: guaranteed bandwidth, low latency, predictable performance. Disadvantage: Limited scalability — each call reserves a fixed path even during silences, and the network can only support as many simultaneous calls as there are physical circuits. It doesn''t scale well to large networks with many users.', 'Networking', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q93', 'A developer stores user login status in both
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q94', 'The language L = {wwᴿ | w ∈ {a, b}*} (even-length palindromes) is:', '["Regular", "Non-deterministic CFL but not deterministic", "Deterministic CFL", "Context-sensitive but not context-free"]', 'Non-deterministic CFL but not deterministic', 'The language {wwᴿ} (even palindromes) requires matching the first half of the string with the reversed second half. A PDA can recognize this non-deterministically — it guesses the midpoint, pushes the first half onto the stack, then matches the second half against the stack. However, a Deterministic PDA cannot figure out where the midpoint is without non-determinism. So it''s Non-deterministic CFL but NOT a deterministic CFL.', 'Automata Theory', 'hard', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q95', '______________is one of the candidate keys chosen by the database designer to uniquely identify the entity set.', '["Super key", "Candidate key", "Social security key", "Primary key"]', 'Primary key', 'Key terminology: Super Key — any set of attributes that uniquely identifies a row. Candidate Key — a minimal super key (no redundant attributes). Primary Key — the ONE candidate key chosen by the designer to be the official unique identifier for the table. It cannot be NULL and must be unique. The primary key is essentially the ''chosen'' candidate key.', 'Database', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q96', 'Which of the following statement about function overloading is TRUE?', '["Overload function have same name but different parameters/type", "Overload function is not supported", "Overload function must have different return type", "Overload function must have the same number of parameters"]', 'Overload function have same name but different parameters/type.', 'Function Overloading allows multiple functions to share the same name as long as they differ in their parameter list (number, type, or order of parameters). Example: add(int a, int b) and add(double a, double b). The compiler determines which version to call based on the argument types at compile time. Return type alone is NOT enough to distinguish overloaded functions.', 'Programming', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q97', 'How does an operating system improve efficiency in a multi-user environment?', '["By allowing only one user to access the system at a time", "By disabling all background services", "By using time-sharing and process scheduling to allocate CPU time fairly among users and processes", "By requiring manual intervention for each task"]', 'By using time-sharing and process scheduling to allocate CPU time fairly among users and processes.', 'In a multi-user environment, many users and processes compete for the CPU simultaneously. The OS uses time-sharing (rapidly switching between processes, giving each a small time slice) and process scheduling algorithms (Round Robin, Priority Scheduling, etc.) to allocate CPU time fairly. This creates the illusion that all users are running simultaneously, maximizing CPU utilization and system efficiency.', 'Operating Systems', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q98', 'Which one of the following is not feature of dynamic web page?', '["Contents can be generated on-the-fly", "Changing content or lively", "Contain the same prebuilt content each time the page is loaded", "Ability to connect to a database"]', 'Contain the same prebuilt content each time the page is loaded.', 'Static web pages contain fixed HTML content that is the same every time the page loads — they don''t change based on user input or a database. Dynamic web pages, by contrast, generate content on-the-fly based on user requests, database queries, session data, etc. ''Contain the same prebuilt content each time loaded'' describes a STATIC page, which is NOT a feature of dynamic pages.', 'Web Development', 'easy', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2018-mid-q99', 'Why should form <input> elements include an associated <label> with the for attribute?', '["It enables offline form storage", "It encrypts user data", "It increases form submission speed", "It improves accessibility: screen readers announce the label when the input is focused"]', 'It improves accessibility: screen readers announce the label when the input is focused.', 'The HTML <label for=''inputId''> element is linked to an <input id=''inputId''> via matching for/id attributes. When a screen reader (used by visually impaired users) focuses on the input field, it reads the associated label aloud, telling the user what the field is for. Labels also make the click target larger (clicking the label focuses the input). This is essential for web accessibility (WCAG standards).', 'Web Development', 'medium', 'Exit Exam 2018 (mid semester)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
